window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a62ea7c829148f07"]={"versions": [{"id": "FIG-a62ea7c829148f07", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Adaptive Platform Timing Extensions (TPS_AdaptivePlatformTimingExtensions), Kapitel 5.4.1 („Specifying an Occurrence Expression“). Das Diagramm modelliert das Metamodell zur Spezifikation formaler Ausdrücke (Occurrence Expressions), mit denen das Auftreten von Timing-Ereignissen bedingt oder gefiltert werden kann.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>TimingDescriptionEvent</code> (Paket/Kontext <code>TimingDescription</code>): Aggregiert über die Komposition <code>+occurrenceExpression</code> mit Kardinalität <code>0..1</code> ein <code>TDEventOccurrenceExpression</code>.\n</li><li><code>TDEventOccurrenceExpression</code>: Dient als Container für alle zur Auswertung des Ausdrucks benötigten Instanzen und die Berechnungsformel. Aggregiert:\n<ul class=\"fig-list\"><li><code>+variable</code> (Kardinalität <code>0..*</code>): Komposition von <code>AutosarVariableInstance</code> (spezialisiert <code>Identifiable</code>).\n</li><li><code>+argument</code> (Kardinalität <code>0..*</code>): Komposition von <code>AutosarOperationArgumentInstance</code> (spezialisiert <code>Identifiable</code>).\n</li><li><code>+mode</code> (Kardinalität <code>0..*</code>): Komposition von <code>TimingModeInstance</code> (spezialisiert <code>Identifiable</code>).\n</li><li><code>+formula</code> (Kardinalität <code>1</code>): Komposition von <code>TDEventOccurrenceExpressionFormula</code>.\n</li></ul>\n</li><li><code>TDEventOccurrenceExpressionFormula</code> (Stereotyp <code>«atpMixedString»</code>, spezialisiert <code>FormulaExpression</code>): Enthält den eigentlichen Ausdruckstext und referenziert:\n<ul class=\"fig-list\"><li><code>+event</code> (Kardinalität <code>0..1</code>, <code>{subsets atpReference}</code>): Referenz auf <code>TimingDescriptionEvent</code>.\n</li><li><code>+mode</code> (Kardinalität <code>0..1</code>): Referenz auf <code>TimingModeInstance</code>.\n</li><li><code>+argument</code> (Kardinalität <code>0..1</code>, <code>{subsets atpReference}</code>): Referenz auf <code>AutosarOperationArgumentInstance</code>.\n</li><li><code>+variable</code> (Kardinalität <code>0..1</code>, <code>{subsets atpReference}</code>): Referenz auf <code>AutosarVariableInstance</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Zur Laufzeit bzw. Evaluierungszeit kapselt <code>TDEventOccurrenceExpression</code> den Definitionsraum für einen Booleschen oder numerischen Filterausdruck: Wenn das referenzierte <code>TimingDescriptionEvent</code> eintritt, wertet die Engine die Formel <code>TDEventOccurrenceExpressionFormula</code> unter Zugriff auf die referenzierten Laufzeitwerte (<code>AutosarVariableInstance</code>, <code>AutosarOperationArgumentInstance</code> oder <code>TimingModeInstance</code>) aus, um festzustellen, ob das Ereignis als gültiges Auftreten gewertet wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Metamodell-Struktur für AUTOSAR AP Timing Extensions. Ein <code>TimingDescriptionEvent</code> darf höchstens eine <code>TDEventOccurrenceExpression</code> aggregieren. Wenn eine <code>TDEventOccurrenceExpression</code> vorhanden ist, ist genau eine Formelinstanz (<code>+formula [1]</code>) obligatorisch, während Variablen-, Argument- und Modus-Instanzen optional mehrfach definiert werden können (<code>0..*</code>). Werkzeuge müssen bei der Validierung sicherstellen, dass die in der <code>«atpMixedString»</code>-Formel verwendeten Bezeichner mit den über die Kompositionen bereitgestellten und per <code>atpReference</code> verknüpften Instanzen übereinstimmen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2c457a4556318ec0", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Adaptive Platform Timing Extensions (TPS_AdaptivePlatformTimingExtensions), Kapitel 5.4.1 („Specifying an Occurrence Expression“). Das Diagramm modelliert das Metamodell zur Spezifikation formaler Ausdrücke (Occurrence Expressions), mit denen das Auftreten von Timing-Ereignissen bedingt oder gefiltert werden kann.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>TimingDescriptionEvent</code> (Paket/Kontext <code>TimingDescription</code>): Aggregiert über die Komposition <code>+occurrenceExpression</code> mit Kardinalität <code>0..1</code> ein <code>TDEventOccurrenceExpression</code>.\n</li><li><code>TDEventOccurrenceExpression</code>: Dient als Container für alle zur Auswertung des Ausdrucks benötigten Instanzen und die Berechnungsformel. Aggregiert:\n<ul class=\"fig-list\"><li><code>+variable</code> (Kardinalität <code>0..*</code>): Komposition von <code>AutosarVariableInstance</code> (spezialisiert <code>Identifiable</code>).\n</li><li><code>+argument</code> (Kardinalität <code>0..*</code>): Komposition von <code>AutosarOperationArgumentInstance</code> (spezialisiert <code>Identifiable</code>).\n</li><li><code>+mode</code> (Kardinalität <code>0..*</code>): Komposition von <code>TimingModeInstance</code> (spezialisiert <code>Identifiable</code>).\n</li><li><code>+formula</code> (Kardinalität <code>1</code>): Komposition von <code>TDEventOccurrenceExpressionFormula</code>.\n</li></ul>\n</li><li><code>TDEventOccurrenceExpressionFormula</code> (Stereotyp <code>«atpMixedString»</code>, spezialisiert <code>FormulaExpression</code>): Enthält den eigentlichen Ausdruckstext und referenziert:\n<ul class=\"fig-list\"><li><code>+event</code> (Kardinalität <code>0..1</code>, <code>{subsets atpReference}</code>): Referenz auf <code>TimingDescriptionEvent</code>.\n</li><li><code>+mode</code> (Kardinalität <code>0..1</code>): Referenz auf <code>TimingModeInstance</code>.\n</li><li><code>+argument</code> (Kardinalität <code>0..1</code>, <code>{subsets atpReference}</code>): Referenz auf <code>AutosarOperationArgumentInstance</code>.\n</li><li><code>+variable</code> (Kardinalität <code>0..1</code>, <code>{subsets atpReference}</code>): Referenz auf <code>AutosarVariableInstance</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Zur Laufzeit bzw. Evaluierungszeit kapselt <code>TDEventOccurrenceExpression</code> den Definitionsraum für einen Booleschen oder numerischen Filterausdruck: Wenn das referenzierte <code>TimingDescriptionEvent</code> eintritt, wertet die Engine die Formel <code>TDEventOccurrenceExpressionFormula</code> unter Zugriff auf die referenzierten Laufzeitwerte (<code>AutosarVariableInstance</code>, <code>AutosarOperationArgumentInstance</code> oder <code>TimingModeInstance</code>) aus, um festzustellen, ob das Ereignis als gültiges Auftreten gewertet wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Metamodell-Struktur für AUTOSAR AP Timing Extensions. Ein <code>TimingDescriptionEvent</code> darf höchstens eine <code>TDEventOccurrenceExpression</code> aggregieren. Wenn eine <code>TDEventOccurrenceExpression</code> vorhanden ist, ist genau eine Formelinstanz (<code>+formula [1]</code>) obligatorisch, während Variablen-, Argument- und Modus-Instanzen optional mehrfach definiert werden können (<code>0..*</code>). Werkzeuge müssen bei der Validierung sicherstellen, dass die in der <code>«atpMixedString»</code>-Formel verwendeten Bezeichner mit den über die Kompositionen bereitgestellten und per <code>atpReference</code> verknüpften Instanzen übereinstimmen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-a62ea7c829148f07", "to": "FIG-2c457a4556318ec0", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
